47	struct SM90_TMA_LOAD_1D
48	{
49	  CUTE_HOST_DEVICE static void
50	  copy(void const* desc_ptr, uint64_t* mbar_ptr, uint64_t cache_hint,
51	       void      * smem_ptr,
52	       int32_t const& crd0)
53	  {
54	#if defined(CUTE_ARCH_TMA_SM90_ENABLED)
55	    uint64_t gmem_int_desc = reinterpret_cast<uint64_t>(desc_ptr);
56	    uint32_t smem_int_mbar = cast_smem_ptr_to_uint(mbar_ptr);
57	    uint32_t smem_int_ptr  = cast_smem_ptr_to_uint(smem_ptr);
58	    cutlass::arch::synclog_emit_tma_load(__LINE__, gmem_int_desc, smem_int_mbar, smem_int_ptr);
59	    asm volatile (
60	      "cp.async.bulk.tensor.1d.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint"
61	      " [%0], [%1, {%3}], [%2], %4;"
62	      :
63	      : "r"(smem_int_ptr), "l"(gmem_int_desc), "r"(smem_int_mbar),
64	        "r"(crd0), "l"(cache_hint)
65	      : "memory");
66	#else
67	    CUTE_INVALID_CONTROL_PATH("Trying to use tma without CUTE_ARCH_TMA_SM90_ENABLED.");
68	#endif
69	  }
70	
71	  struct PREFETCH
72	  {
73	    CUTE_HOST_DEVICE static void
74	    copy(void const* desc_ptr,
75	         int32_t const& crd0)
76	    {
77	  #if defined(CUTE_ARCH_TMA_SM90_ENABLED)
78	      uint64_t gmem_int_desc = reinterpret_cast<uint64_t>(desc_ptr);
79	      asm volatile (
80	        "cp.async.bulk.prefetch.tensor.1d.L2.global"
81	        " [%0, {%1}];"
82	        :
83	        : "l"(gmem_int_desc),
84	          "r"(crd0)
85	        : "memory");
86	  #else
87	      CUTE_INVALID_CONTROL_PATH("Trying to use tma without CUTE_ARCH_TMA_SM90_ENABLED.");
88	  #endif
89	    }
90	  };
91	};
