55	//////////////////////////////////////////////////////////////////////////////////////////////////////
56	/// Barriers are 64-bit of user-managed information used in broadly two types syncronization patterns
57	/// 1) arrive/wait on threads (usage: cp.async and warp-specialized kernels)
58	/// 2) transaction-based (usage: TMA transaction where a CTA issues one transaction)
59	//////////////////////////////////////////////////////////////////////////////////////////////////////
60	
61	// Initialize barrier present in shared memory
62	CUTE_HOST_DEVICE
63	void
64	initialize_barrier(uint64_t& smem_barrier,                 // 64 bits user-manged barrier in smem
65	                   int thread_count = 1)                   // Thread count expected to arrive/wait on this barrier
66	{
67	#if defined(CUTE_ARCH_TMA_SM90_ENABLED)
68	  uint32_t smem_int_ptr = cast_smem_ptr_to_uint(&smem_barrier);
69	  asm volatile ("mbarrier.init.shared::cta.b64 [%0], %1;\n"
70	    :: "r"(smem_int_ptr),
71	       "r"(thread_count));
72	#endif
73	}
74	
75	// Set the number of bytes transfered per transaction and perform an arrive operation as well
76	CUTE_HOST_DEVICE
77	void
78	set_barrier_transaction_bytes(uint64_t& smem_barrier,      // 64 bits user-manged barrier in smem
79	                              uint32_t bytes)              // Number of bytes transfered by per TMA transaction
80	{
81	#if defined(CUTE_ARCH_TMA_SM90_ENABLED)
82	  uint32_t smem_int_ptr = cast_smem_ptr_to_uint(&smem_barrier);
83	  asm volatile ("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;\n"
84	    :: "r"(smem_int_ptr),
85	       "r"(bytes));
86	#endif
87	}
88	
89	// Barrier wait
90	CUTE_HOST_DEVICE
91	void
92	wait_barrier(uint64_t& smem_barrier,                       // 64 bits user-manged barrier in smem
93	             int phase_bit)                                // Current phase bit the barrier waiting to flip
94	{
95	#if defined(CUTE_ARCH_TMA_SM90_ENABLED)
96	  uint32_t smem_int_ptr = cast_smem_ptr_to_uint(&smem_barrier);
97	  asm volatile(
98	    "{\n"
99	    ".reg .pred                P1;\n"
100	    "LAB_WAIT:\n"
101	    "mbarrier.try_wait.parity.shared::cta.b64 P1, [%0], %1;\n"
102	    "@P1                       bra DONE;\n"
103	    "bra                   LAB_WAIT;\n"
104	    "DONE:\n"
105	    "}\n"
106	    :: "r"(smem_int_ptr),
107	       "r"(phase_bit));
108	
109	#endif
110	}
111	
112	// Barrier arrive
113	CUTE_HOST_DEVICE
114	void
115	arrive_barrier(uint64_t& smem_barrier)                      // 64 bits user-manged barrier in smem
116	{
117	#if defined(CUTE_ARCH_TMA_SM90_ENABLED)
118	  uint32_t smem_int_ptr = cast_smem_ptr_to_uint(&smem_barrier);
119	  asm volatile(
120	    "{\n"
121	    ".reg .b64 state; \n"
122	    "mbarrier.arrive.shared::cta.b64   state, [%0];\n"
123	    "}\n"
124	    :: "r"(smem_int_ptr));
125	#endif
126	}
