559	// ════════════════════════════════════════════════════════════════════════
560	//  Canonical Major-K smem stager. The ss-wgmma operand smem tile (MN rows x
561	//  K=16 bf16) MUST be in the CUTLASS Major-K INTERLEAVE layout (wgmma.cuh):
562	//      idx(mn,k) = (k/8)*(MN*8) + mn*8 + (k%8)
563	//  This helper writes ONE such MN x 16 tile, pulling element (mn, k) from a
564	//  caller-provided accessor `src(mn, kbase + k)`. Routing the source axis
565	//  through the accessor is what lets the SAME wgmma issue (TransA=0/TransB=0,
566	//  the substrate-validated orientation) serve fwd / dX / dW: the staging loop
567	//  transposes physically; the engine never leaves the gated path.
568	//
569	//  Cooperative over `nthreads` threads starting at thread `t0` (a warpgroup).
570	// ════════════════════════════════════════════════════════════════════════
571	template <int MN, typename Src>
572	__device__ __forceinline__ void stage_kmajor_tile(
573	        __nv_bfloat16* smem_tile, int kbase, Src src, int t0, int nthreads) {
574	    // MN*16 elements, each thread strides.
575	    #pragma unroll 1
576	    for (int i = t0; i < MN * wgs::kWgmmaAtomK; i += nthreads) {
577	        const int mn = i / wgs::kWgmmaAtomK;
578	        const int k  = i % wgs::kWgmmaAtomK;
579	        const int dst = (k >> 3) * (MN * 8) + mn * 8 + (k & 7);
580	        smem_tile[dst] = src(mn, kbase + k);
581	    }
582	}
583	
584	// ════════════════════════════════════════════════════════════════════════
585	//  Flat-gmem K-major tile SOURCES (the cp.async RING enabler). The generic
586	//  engine takes accessor-shaped sources `src(mn, k)`; when the source is a
587	//  FLAT row-major gmem region whose rows are K-CONTIGUOUS and 16B-aligned
588	//  (base/ld multiples of 8 bf16 — true of every fwd/dX operand: the bf16 acts
589	//  and the C1/C1-T weight cache), the staging can be issued as 16-byte
590	//  cp.async copies instead of the 2-byte LDG→reg→STS element loop. These two
591	//  POD sources carry exactly the information that decision needs:
592	//    operator()(mn,k)        — the scalar accessor (identical semantics to the
593	//                              lambdas they replace; the S=1 serial path and
594	//                              any non-ring build still stage through it).
595	//    chunk16(mn,kbase,half)  — gmem address of the 16B half-row (8 bf16) that
596	//                              lands at smem offset half·(MN·8)+mn·8 of the
597	//                              canonical Major-K interleave tile.
598	//    row_valid(mn)           — false ⇒ the row is PAD (ragged N-tile): the
599	//                              ring zero-fills smem and must NOT read gmem
600	//                              (mirrors the `nn < Nout ? .. : 0` guard).
601	//  The A-form has no guard (the engine's A rows are always readable — the
602	//  caller guarantees the region, exactly as the current lambdas assume); the
603	//  B-form guards rows beyond `rows_valid`. A trait gates the engine's ring
604	//  branch at COMPILE TIME, so the dW path (lambda sources; transposed-strided
605	//  reads — ring blocker (b), out of scope) keeps the synchronous staging
606	//  unchanged.
607	// ════════════════════════════════════════════════════════════════════════
608	namespace decprim = ::sg::sm90::primitives;
609	
610	struct DecGmemTileSrcA {
611	    const __nv_bfloat16* base;   // row 0, k 0 (16B-aligned)
612	    int ld;                      // row stride in ELEMENTS (multiple of 8)
613	    __device__ __forceinline__ __nv_bfloat16 operator()(int mn, int k) const {
614	        return base[(int64_t)mn * ld + k];
615	    }
616	    __device__ __forceinline__ const void* chunk16(int mn, int kbase, int half) const {
617	        return base + (int64_t)mn * ld + kbase + half * 8;
618	    }
619	    __device__ __forceinline__ bool row_valid(int) const { return true; }
620	};
621	
622	struct DecGmemTileSrcB {
623	    const __nv_bfloat16* base;   // row n0, k 0 (16B-aligned)
624	    int ld;                      // row stride in ELEMENTS (multiple of 8)
625	    int rows_valid;              // rows >= this are pad (zero, never read)
626	    __device__ __forceinline__ __nv_bfloat16 operator()(int mn, int k) const {
627	        return mn < rows_valid ? base[(int64_t)mn * ld + k] : __float2bfloat16(0.f);
628	    }
629	    __device__ __forceinline__ const void* chunk16(int mn, int kbase, int half) const {
630	        return base + (int64_t)mn * ld + kbase + half * 8;
631	    }
632	    __device__ __forceinline__ bool row_valid(int mn) const { return mn < rows_valid; }
633	};
634	
635	template <typename T> struct DecTileSrcIsGmem { static constexpr bool value = false; };
636	template <> struct DecTileSrcIsGmem<DecGmemTileSrcA> { static constexpr bool value = true; };
637	template <> struct DecTileSrcIsGmem<DecGmemTileSrcB> { static constexpr bool value = true; };
638	
639	// ════════════════════════════════════════════════════════════════════════
640	//  Unpipelined single-CTA batch GEMM: D[M,N] = Σ_k A[m,k]·B[n,k], bf16 operands
641	//  (accessor-sourced + Major-K staged), fp32 accumulator, ascending-k. M is
642	//  kTileM (kAtomsM stacked m64 atoms — the substrate's unexercised TILE_M
643	//  stacking, gated here). N is a compile-time wgmma atom width. K=k_steps*16.
644	//
645	//  The consumer warpgroup (the FULL CTA's 256 threads act as producer+consumer
646	//  here in the SIMPLE unpipelined form: all 256 stage, then warpgroup 0's 128
647	//  threads — actually wgmma is warpgroup-scoped (.aligned, 128 threads). We use
648	//  ONE warpgroup (threads 0..127) for the MMA; staging uses all 256 threads.
649	//
650	//  smem: one A tile (64x16) + one B tile (Nx16) per stacked atom row, reused
651	//  across k-steps (unpipelined: stage k, mma k, repeat). Two buffers (A,B) of
652	//  the largest atom. Accumulators live in registers (kAtomsM fragments).
653	//
654	//  ACC OUTPUT: written via accessor `out(m_global, n_local, value)` so the
655	//  caller routes the fp32 result (the fragment decode gives (row,col) within the
656	//  64xN atom; the caller adds the atom's M-base).
657	//
658	//  GENERALITY (the M and N must be caller-parameterized, NOT hardwired to the
659	//  token tile — a dW GEMM has M = Nout in {99,128,384,512} and the fwd GEMMs
660	//  have N in {128,384,512}). This helper computes ONE M-block of `m_atoms`
661	//  stacked m64 atoms (rows [mbase0, mbase0 + m_atoms*64)) for ONE N-tile of the
662	//  compile-time atom width N. The CALLER loops M-atom-blocks × N-tiles to cover
663	//  arbitrary (M, N). MaxAtomsM bounds the register accumulator array
664	//  (compile-time); only `m_atoms` (<= MaxAtomsM) atoms are issued at runtime.
665	//  `n_real <= N` lets the caller mark the valid column count for a ragged N-tile
666	//  (e.g. head V=99 in a N=128 tile) so the epilogue suppresses pad columns; the
667	//  wgmma still runs the full N (pad operands are zero so pad outputs are inert).
668	//
669	//  Determinism: ascending-k, one CTA owns the tile end-to-end, no atomics.
670	// ════════════════════════════════════════════════════════════════════════
671	// `prof_phase` (default -1) is the FINE-profiler phase tag (0 = fwd ring, 1 = dX
672	// ring) used ONLY when SG_DEC_PROFILE && SG_DEC_PROFILE_FWD_FINE is set — the
673	// fwd wrappers pass 0, the dX wrappers pass 1, dW leaves the default. It is a
674	// trailing defaulted scalar that is NEVER referenced unless that pair is set
675	// (then it selects which g_dec_prof_fwd_fine phase the engine stamps), so the
676	// selftest's existing 9-arg calls still compile AND the shipped PTX is byte-
677	// identical (an unreferenced trailing defaulted arg is dropped by the optimizer;
678	// PTX-verified OFF-vs-baseline).
679	// `pipeBars` (default nullptr) is the producer/consumer mbarrier-words base for the
680	// PIPE=2 engine (entry b) — 2·RS `unsigned long long` words (full[RS] then empty[RS]),
681	// carved from the kernel's DecTcSmem::pipe_bars. It is dereferenced ONLY inside the
682	// `if constexpr (kDecFwdPipeEngine)` sub-branch (PIPE=2), which is compiled OUT for
683	// PIPE 0|1 — so the nullptr the wrappers pass on the shipped build is UNREFERENCED
684	// and dropped by the optimizer (byte-identical PTX, like prof_phase). dW + the TP
685	// fp32-W overloads + the selftest's 9-arg calls leave it null (they never take the
686	// ring → !kRingAsync → the engine sub-branch is unreachable for them).
687	template <int N, int MaxAtomsM, typename SrcA, typename SrcB, typename Out>
688	__device__ void tc_gemm_block_unpipelined(
689	        int mbase0, int m_atoms, int n_real, int k_steps,
690	        SrcA srcA, SrcB srcB, Out out,
691	        __nv_bfloat16* smemA, __nv_bfloat16* smemB,
692	        unsigned long long* pipeBars = nullptr,
693	        int prof_phase = -1) {
694	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
695	    (void)prof_phase; (void)pipeBars;
696	    const int tid = threadIdx.x;
697	    const int nthreads = blockDim.x;            // 256
698	    const bool in_wg0 = (tid < 128);
699	    const int tid_wg = tid & 127;
700	    constexpr int S = kDecTcStages;
701	
702	    // ── M-ATOM-INTERLEAVED wgmma pipeline (overlaps the tensor pipe + HALVES the
703	    //    redundant B-tile staging; THE hill-climb win, task #13). The OLD body ran
704	    //    each stacked m64 atom's k-chain to completion SEQUENTIALLY (atom0 chain →
705	    //    atom0 epilogue → atom1 chain → …): every wgmma was followed by a per-issue
706	    //    wait, the shared B (weight) tile was re-staged ONCE PER ATOM, and the atom-a
707	    //    epilogue stores interleaved with atom-a+1's first wgmma (ptxas C7515).
708	    //
709	    //    Here, atoms are processed in GROUPS of kIL (= min(MaxAtomsM, kDecMaxIL)).
710	    //    Within a group, EACH k-step issues the kIL wgmmas (one per atom) BACK-TO-
711	    //    BACK into their OWN fp32 fragments, sharing ONE staged B-tile, before the
712	    //    single per-k wait. Two wins: (1) the kIL atoms are INDEPENDENT (distinct
713	    //    M-rows / accumulators) → the tensor pipe overlaps their MMA execution
714	    //    instead of paying each latency raw; (2) the B-tile is staged ONCE for the
715	    //    whole group instead of kIL times → the (HBM-bound) weight-operand traffic
716	    //    drops kIL×. Measured: d=1024 B=16384 step 2084→1624 ms (+28% TF/s).
717	    //
718	    //    kIL is CAPPED (kDecMaxIL=2) so the register/smem cost is bounded regardless
719	    //    of m_atoms (the dW micro-gate runs Nout=512 → 8 atoms; an 8-wide interleave
720	    //    would need 8×64 accumulator regs). Groups reuse the SAME ring slots
721	    //    sequentially (like the old atom loop). Per-atom accumulation stays
722	    //    ASCENDING-k (k=0 overwrite, k>0 add) → numerics bit-identical + A/A/A
723	    //    determinism UNCHANGED. Ring stages kIL A-tiles (slot sl, atom-in-group ai at
724	    //    +ai·kDecTcSmemA1) + ONE shared B-tile; smem{A} must hold kIL·kDecTcStages
725	    //    tiles (DecTcSmem sizes it for kAtomsM=production max).
726	    constexpr int kIL = (MaxAtomsM < kDecMaxIL) ? MaxAtomsM : kDecMaxIL;
727	    wgs::WgmmaAccum<N> acc[kIL];                 // kIL live fragments per group
728	
729	    // Stage k-tile for a group of `g_atoms` (<= kIL) atoms based at `gbase`: the
730	    // g_atoms A-tiles (rows gbase+ai·64) + the shared B-tile, into ring slot k % S.
731	    auto stage_k = [&] (int gbase, int g_atoms, int k) {
732	        const int sl = k % S;
733	        for (int ai = 0; ai < g_atoms; ++ai) {
734	            const int mbase = gbase + ai * wgs::kWgmmaAtomM;
735	            stage_kmajor_tile<wgs::kWgmmaAtomM>(
736	                smemA + ((int64_t)sl * kIL + ai) * kDecTcSmemA1, k * wgs::kWgmmaAtomK,
737	                [&] (int mn, int kk) { return srcA(mbase + mn, kk); }, tid, nthreads);
738	        }
739	        stage_kmajor_tile<N>(
740	            smemB + (int64_t)sl * kDecTcSmemB1, k * wgs::kWgmmaAtomK,
741	            [&] (int mn, int kk) { return srcB(mn, kk); }, tid, nthreads);
742	    };
743	    // Issue the group's g_atoms wgmmas for staged slot k (k=0 overwrite else accum).
744	    // `rs` is the ring-slot modulus (kDecTcStages for the scalar/dW path; the
745	    // deeper kDecFwdStages for the fwd/dX cp.async ring). Both are compile-time at
746	    // every call site so the % folds; the wgmma ISSUE SEQUENCE (ascending k, k=0
747	    // overwrite / k>0 accumulate) is identical regardless of rs — only the slot
748	    // the operands were staged into differs, so the fp32 accumulation order is
749	    // bit-identical (parity / A/A/A preserved).
750	    auto issue_k = [&] (int g_atoms, int k, int rs) {
751	        const int sl = k % rs;
752	        wgs::SmemDesc dB = wgs::make_desc_B_kmajor<N, wgs::kSwizzleNone>(
753	            smemB + (int64_t)sl * kDecTcSmemB1);
754	        #pragma unroll
755	        for (int ai = 0; ai < kIL; ++ai) {
756	            if (ai >= g_atoms) break;
757	            wgs::SmemDesc dA = wgs::make_desc_A_kmajor<wgs::kWgmmaAtomM, wgs::kSwizzleNone>(
758	                smemA + ((int64_t)sl * kIL + ai) * kDecTcSmemA1);
759	            if (k == 0) wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/0, 0, 0>(acc[ai], dA, dB);
760	            else        wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/1, 0, 0>(acc[ai], dA, dB);
761	        }
762	    };
763	
764	    // ── cp.async DOUBLE-BUFFERED RING (campaign RING; unblocked by C1/C1-T).
765	    //    Selected at COMPILE TIME when BOTH sources are flat-gmem K-major rows
766	    //    (DecGmemTileSrc*, i.e. the fwd/dX wrappers) and the ring has >= 2 slots.
767	    //    Same slot ring, same ascending-k issue order, same __syncthreads
768	    //    choreography as the synchronous path — ONLY the staging TRANSPORT
769	    //    changes: the per-element 2-byte LDG→reg→STS loop (≈16 dependent
770	    //    load/store pairs per thread per k-tile, latency exposed in register-
771	    //    window-limited chunks) becomes 2 fire-and-forget 16-byte
772	    //    cp.async.cg copies per thread (LDGSTS: gmem→smem direct, no register
773	    //    round-trip, the WHOLE tile in flight at once) issued while wg0's
774	    //    wgmmas on the PREVIOUS tile execute in the tensor pipe. The
775	    //    per-thread cp_async_wait_group<0> + ONE fence.proxy.async + the
776	    //    existing __syncthreads publish the slot before its first wgmma — the
777	    //    primitives.cuh contract (issue→commit→wait→barrier→read), i.e. the
778	    //    silicon-validated tile_pipeline handshake.
779	    //    NUMERICS: identical bytes land in identical smem offsets in the same
780	    //    k-order; the wgmma sequence is untouched → results bit-identical to
781	    //    the synchronous staging (fp64-oracle parity / A/A/A by construction).
782	    //    dW keeps the synchronous staging (lambda sources: transposed-strided
783	    //    acts reads = ring blocker (b), needs TMA-with-transpose; out of scope).
784	    constexpr bool kRingAsync = (S > 1)
785	        && DecTileSrcIsGmem<SrcA>::value && DecTileSrcIsGmem<SrcB>::value;
786	
787	    // ── FINE-profiler accumulators (SG_DEC_PROFILE && SG_DEC_PROFILE_FWD_FINE).
788	    //    Thread-0-only clock64 deltas, summed across ALL M-atom groups + k-steps
789	    //    of THIS engine call, atomicMax'd into g_dec_prof_fwd_fine ONCE after the
790	    //    group loop (= the slowest CTA's critical path per sub-phase). Compiled
791	    //    out entirely (no vars, no clock64, no atomic) unless the pair is set →
792	    //    byte-identical when off. Only the kRingAsync (fwd/dX) path stamps; the dW
793	    //    !kRingAsync path never reaches these TICs.
794	#if defined(SG_DEC_PROFILE) && SG_DEC_PROFILE_FWD_FINE
795	    unsigned long long _f_issue = 0, _f_wait = 0, _f_wgmma = 0, _f_epi = 0, _f_bar = 0;
796	    unsigned long long _t0 = 0;
797	    const bool _prof_t0 = (tid == 0);
798	    #define SG_FINE_TIC() do { if (_prof_t0) _t0 = clock64(); } while (0)
799	    #define SG_FINE_ACC(acc) do { if (_prof_t0) (acc) += clock64() - _t0; } while (0)
800	#else
801	    #define SG_FINE_TIC() do {} while (0)
802	    #define SG_FINE_ACC(acc) do {} while (0)
803	#endif
804	
805	    // Loop M-atom GROUPS of kIL; each group runs its own k-chain into kIL fragments.
806	    #pragma unroll 1
807	    for (int g0 = 0; g0 < m_atoms; g0 += kIL) {
808	        const int gbase = mbase0 + g0 * wgs::kWgmmaAtomM;
809	        const int g_atoms = (m_atoms - g0) < kIL ? (m_atoms - g0) : kIL;
810	        if constexpr (kRingAsync) {
811	            (void)stage_k;   // the scalar stager is the !ring branch's transport
812	            // RING DEPTH for the fwd/dX path. PIPE=0 → RS==kDecTcStages (the
813	            // shipped S=2 double-buffer), and the RS==2 sub-branch below is the
814	            // ORIGINAL ring VERBATIM → byte-identical PTX. PIPE=1 → RS=2..4 keeps
815	            // RS-1 cp.async groups in flight (deeper prefetch; the deeper sub-branch).
816	            constexpr int RS = kDecFwdStages;
817	            // Stage the group's k-tile `kk` into ring slot kk % RS via 16B cp.async:
818	            // g_atoms A(64×16) tiles + the ONE shared B(N×16) tile (the M-atom-
819	            // interleave structure, verbatim). Chunk space is FLAT and fixed
820	            // (kIL·64·2 A-halves then N·2 B-halves) so every thread's share is
821	            // static; halves of a dead atom (ai >= g_atoms) are skipped (their
822	            // smem is never read — issue_k stops at g_atoms). Each 16B half-row
823	            // (mn, k 8·half..8·half+7) lands at the canonical Major-K interleave
824	            // offset half·(MN·8)+mn·8 — the same map stage_kmajor_tile writes and
825	            // the same chunking tile_pipeline.cuh::pipeline_produce_ktile issues.
826	            auto stage_k_async = [&] (int kk) {
827	                const int sl = kk % RS;
828	                const int kb = kk * wgs::kWgmmaAtomK;
829	                constexpr int kAChunks = kIL * wgs::kWgmmaAtomM * 2;
830	                constexpr int kChunks  = kAChunks + N * 2;
831	                #pragma unroll 1
832	                for (int v = tid; v < kChunks; v += nthreads) {
833	                    if (v < kAChunks) {
834	                        const int ai = v / (wgs::kWgmmaAtomM * 2);
835	                        if (ai < g_atoms) {
836	                            const int r  = v - ai * (wgs::kWgmmaAtomM * 2);
837	                            const int mn = r >> 1, half = r & 1;
838	                            decprim::cp_async_cg_16(
839	                                smemA + ((int64_t)sl * kIL + ai) * kDecTcSmemA1
840	                                      + half * (wgs::kWgmmaAtomM * 8) + mn * 8,
841	                                srcA.chunk16(gbase + ai * wgs::kWgmmaAtomM + mn, kb, half));
842	                        }
843	                    } else {
844	                        const int r  = v - kAChunks;
845	                        const int mn = r >> 1, half = r & 1;
846	                        __nv_bfloat16* dst = smemB + (int64_t)sl * kDecTcSmemB1
