1133	//  THIN ORIENTATION WRAPPERS over tc_gemm_block_unpipelined. These reproduce
1134	//  the THREE accessor patterns the engine is silicon-validated on
1135	//  (decoder_tc_selftest.cu / test_decoder_tc.py 13/13): fwd (Y=X·Wᵀ, no
1136	//  transpose), dX (dX=dY·W, W transposed-staged), dW (dW=dYᵀ·X, BOTH
1137	//  transposed-staged, K=T). The driver calls THESE — it never re-derives the
1138	//  staging (the no-suppression / reuse-the-validated-unit discipline).
1139	//
1140	//  All operands are HBM bf16 row-major. The caller passes one A(64×16) + one
1141	//  B(Nmax×16) smem staging pair (the engine reuses them across k-steps). N is
1142	//  the compile-time wgmma atom width (128 for in/out/ff dX-N=d; the fwd loops
1143	//  N-tiles internally). Accumulation is fp32; output written via the accessor.
1144	// ════════════════════════════════════════════════════════════════════════
1145	
1146	// (fwd) Y[M,Nout] = X[M,Kin] @ W[Nout,Kin]ᵀ.  Tiles N over [0,Nout) in width-N
1147	// atoms (Nout∈{d=128, 3d=384, dff=512}). M = kTileM (kAtomsM stacked atoms).
1148	// Y is written row-major [M, Nout] at base `Yout` with row stride Nout.
1149	// NOTE on weights: W is the PRE-STAGED bf16 cache (C1, dec_wbf_bind) — the
1150	// fp32→bf16 conversion happened ONCE per step in dectc_wbf_convert with the
1151	// identical deterministic rounding the old on-read accessor performed, so the
1152	// staged operand VALUES are bit-identical. Both operands are flat-gmem K-major
1153	// → the engine's cp.async double-buffered ring stages them (RING).
1154	// `pipeBars` (default nullptr): the PIPE=2 producer/consumer mbarrier-words base
1155	// (DecTcSmem::pipe_bars). Forwarded to the engine; dereferenced ONLY in its PIPE=2
1156	// sub-branch (compiled out for PIPE 0|1 → the nullptr default is unreferenced and
1157	// dropped → byte-identical). The fwd/dX driver threads sm.pipe_bars under
1158	// #if SG_TUNED_DEC_FWD_PIPE == 2; on the shipped build it passes nothing (default).
1159	template <int N>
1160	__device__ __forceinline__ void dectc_gemm_fwd(
1161	        const __nv_bfloat16* __restrict__ X, const __nv_bfloat16* __restrict__ W,
1162	        __nv_bfloat16* __restrict__ Yout, int Kin, int Nout,
1163	        __nv_bfloat16* sA, __nv_bfloat16* sB, unsigned long long* pipeBars = nullptr) {
1164	    const int k_steps = Kin / wgs::kWgmmaAtomK;
1165	    for (int n0 = 0; n0 < Nout; n0 += N) {
1166	        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
1167	        // A: token rows of X (bf16 acts), K-contiguous. B: rows n0.. of the
1168	        // PRE-STAGED bf16 cache (C1) -- a pure bf16 copy, values bit-identical
1169	        // to the on-read path. Both flat-gmem K-major -> the engine selects the
1170	        // cp.async double-buffered ring (RING); same accessor semantics as the
1171	        // lambdas these replace (incl. the `nn < Nout ? .. : 0` pad guard).
1172	        DecGmemTileSrcA srcA{X, Kin};
1173	        DecGmemTileSrcB srcB{W + (int64_t)n0 * Kin, Kin, Nout - n0};
1174	        auto out  = [&] (int m, int n, float v) {
1175	            Yout[(int64_t)m * Nout + n0 + n] = __float2bfloat16(v); };
1176	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kAtomsM>(
1177	            0, kAtomsM, n_real, k_steps, srcA, srcB, out, sA, sB, pipeBars SG_DEC_FINE_FWD);
1178	    }
