862	#ifdef SG_DEC_PROFILE
863	        __syncthreads(); unsigned long long _c2 = clock64();
864	        if (threadIdx.x == 0) { prof_fwd += _c1 - _c0; prof_bwd += _c2 - _c1; }
865	#endif
866	        if (threadIdx.x == 0) nll_acc += nll;
867	        __syncthreads();
868	    }
869	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
870	#ifdef SG_DEC_PROFILE
871	    if (threadIdx.x == 0) {
872	        atomicMax(&g_dec_prof_max[0], prof_fwd);
873	        atomicMax(&g_dec_prof_max[1], prof_bwd);
874	    }
875	    unsigned long long _b1a = (threadIdx.x == 0) ? clock64() : 0;
876	#endif
877	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
878	#ifdef SG_DEC_PROFILE
879	    if (threadIdx.x == 0) { unsigned long long _b1b = clock64(); atomicMax(&g_dec_prof_max[2], _b1b - _b1a); }
880	#endif
881	
882	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
883	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
884	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
885	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
886	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
887	    // Spec build: the 5-arg form (with dwt_base) binds the transpose scratch when
888	    // SG_TUNED_DEC_DW_STAGE=1; the scalar default uses the original 4-arg overload
889	    // VERBATIM (no extra arg in the PTX) → byte-identical.
890	    if (threadIdx.x == 0) {
891	#if SG_TUNED_DEC_DW_STAGE
892	        dectc::dectc_build_dw_specs(acts, B, T, sm.spec, dwt_base);
893	#else
894	        dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
895	#endif
896	    }
897	    __syncthreads();
898	    dectc::DecDwSpec* spec = sm.spec;
899	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
900	    // CONTIGUOUS-TRANSPOSE staging (SG_TUNED_DEC_DW_STAGE=1): pre-transpose the 9
901	    // weights' dY/X into the K-major scratch the specs bind, so the SINGLE-CTA dW
902	    // GEMM (dectc_dw_run_tile, the proof wrapper) reads them via the proven
903	    // cp.async ring (DecGmemTileSrc*). Runs AFTER B1 (all acts complete) + ONE
904	    // grid barrier so a CTA's dW tile reads dYt/Xt written by ANY CTA (the
905	    // transpose is grid-strided, owner ≠ the dW tile owner). GATED to kDwG==1
906	    // (the wired proof path): when split-K is active the _splitk path keeps the
907	    // lambda gather, so the transpose would be wasted work — skip it (and the
908	    // barrier). #if-guarded so the scalar default emits NEITHER the transpose call
909	    // NOR the extra barrier (byte-identical control flow + grid-barrier count). ──
910	#if SG_TUNED_DEC_DW_STAGE
911	    if constexpr (dectc::kDecDwTransposeActive) {
912	        dectc::dectc_dw_transpose_operands(spec, cta, nCTA);
913	        bar.sync();   // B1b: all transposed operands visible before any dW GEMM read
914	    }
915	#endif
916	#ifdef SG_DEC_PROFILE
917	    __syncthreads(); unsigned long long _dwa = (threadIdx.x == 0) ? clock64() : 0;
918	#endif
919	    if (kDwG > 1) {
920	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
921	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
922	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
923	            const int gt = item / kDwG, kc = item % kDwG;
924	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
925	        }
926	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
927	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
928	    } else {
929	        for (int gt = cta; gt < n_dw; gt += nCTA)
930	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
931	    }
932	#ifdef SG_DEC_PROFILE
933	    __syncthreads();
934	    if (threadIdx.x == 0) { unsigned long long _dwb = clock64(); atomicMax(&g_dec_prof_max[3], _dwb - _dwa); }
935	    unsigned long long _gaa = (threadIdx.x == 0) ? clock64() : 0;
936	#endif
937	    dectc::dectc_dw_biases(spec, grad, cta, nCTA);
938	    dectc::dectc_embed_owner_scan(acts, embed_row_start, embed_perm, T, grad, cta, nCTA);
939	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
940	    // Loss reduce (fp64) by CTA 0.
941	    if (cta == 0 && threadIdx.x == 0) {
942	        double s = 0.0;
943	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
944	        *tok.loss_out = (float)(s / (double)B);
945	    }
946	#ifdef SG_DEC_PROFILE
947	    if (threadIdx.x == 0) { unsigned long long _gab = clock64(); atomicMax(&g_dec_prof_max[4], _gab - _gaa); }
948	#endif

1	// csrc/backends/cuda/sm_90/wgmma_selftest.cu
2	// ─────────────────────────────────────────────────────────────────────────
3	// Minimal nvcc test TU for the R2 tensor-core substrate (wgmma.cuh /
4	// tile_pipeline.cuh). Compiled via torch.utils.cpp_extension.load() by
5	// tests/hw/test_wgmma_substrate.py (NOT via setup.py — this TU is test-only
6	// and is never part of the shipped build glob).
7	//
8	// Exposes torch-callable entry points that run small, seconds-scale CORRECTNESS
9	// gates on a single CTA (one warpgroup = 128 threads, blockDim.x=128). These
10	// are contention-immune correctness checks, NOT timed benchmarks (perf is a
11	// later quiet-GPU phase): tiny grids, < 1 GB allocations.
12	//
13	// Gates exercised here (driven from python):
14	//   (a) single-tile bf16 GEMM (m64×N×16) vs an fp32 reference of the
15	//       bf16-rounded inputs, over multiple N incl. ragged edges;
16	//   (b) multi-tile K-loop accumulation (the k16 chain over K=128);
17	//   (c) pipelined variant (producer/consumer, 2-3 stages) — same numerics;
18	//   (d) determinism: same inputs -> bitwise-identical outputs;
19	//   (e) occupancy / refuse probe for an oversized dynamic-smem request.
20	//
21	// All operands are bf16 in smem (the design's input dtype), fp32 accumulators.
22	// ─────────────────────────────────────────────────────────────────────────
23	#include <torch/extension.h>
24	#include <c10/cuda/CUDAStream.h>
25	#include <c10/cuda/CUDAException.h>
26	#include <cuda_runtime.h>
27	#include <cuda_bf16.h>
28	#include <cuda/std/utility>   // cuda::std::pair (descriptor-pair return)
29	#include <cstdint>
30	
31	#include "csrc/backends/cuda/sm_90/wgmma.cuh"
32	#include "csrc/backends/cuda/sm_90/tile_pipeline.cuh"
33	
34	namespace wgs = sg::sm90::wgs;
35	
36	// =========================================================================
37	//  Helpers shared by the kernels.
38	//
39	//  smem operand layout — the CUTLASS-canonical Major-K (INTERLEAVE/no-swizzle)
40	//  layout the ss-wgmma actually requires (NOT a plain row-major block). For an
41	//  operand of MN rows × K(=16) bf16, element (mn,k) lands at the bf16 index
42	//      idx(mn,k) = (k/8)*(MN*8) + mn*8 + (k%8)
43	//  i.e. K=16 is two stacked 8-wide core matrices, each an MN×8 row-major block.
44	//  Both A (MN=64) and B (MN=N) are staged this way; the wgmma then computes the
45	//  TN product  D[m,n] = sum_k A[m,k]·B[n,k]  with BOTH operands Major-K
46	//  (TransA=0, TransB=0 — Major::K==0 in cute). The python reference computes
47	//  exactly D = einsum("smk,snk->mn", A_bf16, B_bf16) over the SAME logical
48	//  [k_step,MN,16] tensors (global stays row-major; only the smem staging is
49	//  canonicalized). See make_desc_{A,B}_kmajor in wgmma.cuh.
50	// =========================================================================
51	
52	// Canonical Major-K bf16 smem index for element (mn,k) of an MN×16 tile.
53	__device__ __forceinline__ int kmajor_idx(int mn, int k, int MN) {
54	    return (k >> 3) * (MN * 8) + mn * 8 + (k & 7);
55	}
56	
57	template <int N>
58	__global__ void __launch_bounds__(128)
59	gemm_single_tile_kernel(
60	    const __nv_bfloat16* __restrict__ gA,   // [64*16] row-major M×K
61	    const __nv_bfloat16* __restrict__ gB,   // [N*16]  row-major N×K
62	    float* __restrict__ gD,                 // [64*N]  row-major M×N out
63	    int k_steps                              // number of 16-wide K tiles
64	) {
65	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
66	    // smem operand tiles: one A (64×16) + one B (N×16) per K-step, all staged.
67	    // For the single-tile / K-loop gates we stage ALL k_steps contiguously so
68	    // the descriptor generator just advances a pointer (no pipelining).
69	    extern __shared__ __nv_bfloat16 smem[];
70	    __nv_bfloat16* sA = smem;                       // [k_steps][64*16]
71	    __nv_bfloat16* sB = sA + (size_t)k_steps * 64 * 16; // [k_steps][N*16]
72	
73	    const int tid = threadIdx.x;  // 0..127 (one warpgroup)
74	
75	    // Cooperative load of all K-tiles into smem, SCATTERED from global
76	    // row-major ([k_step,MN,16]) into the canonical Major-K core-matrix layout
77	    // make_desc_*_kmajor requires. Each thread copies elements at its stride
78	    // and routes them via kmajor_idx. 64*16=1024 A elems + N*16 B elems / step.
79	    for (int k = 0; k < k_steps; ++k) {
80	        const __nv_bfloat16* aSrc = gA + (size_t)k * 64 * 16;   // row-major MxK
81	        const __nv_bfloat16* bSrc = gB + (size_t)k * N * 16;    // row-major NxK
82	        __nv_bfloat16* aDst = sA + (size_t)k * 64 * 16;
83	        __nv_bfloat16* bDst = sB + (size_t)k * N * 16;
84	        for (int i = tid; i < 64 * 16; i += 128) {
85	            int m = i >> 4, kk = i & 15;                 // global (m,k), K=16
86	            aDst[kmajor_idx(m, kk, 64)] = aSrc[i];
87	        }
88	        for (int i = tid; i < N * 16; i += 128) {
89	            int n = i / 16, kk = i % 16;
90	            bDst[kmajor_idx(n, kk, N)] = bSrc[i];
91	        }
92	    }
93	    __syncthreads();
94	
95	    wgs::WgmmaAccum<N> acc;  // fp32 fragment, N/2 regs/thread
96	
97	    // Descriptor generator: k-step k → {descA, descB} for the pre-staged tiles
98	    // (each tile already in canonical Major-K layout; the builder encodes the
99	    // canonical LBO=MN*16 / SBO=128 from the MN extent — see wgmma.cuh).
100	    auto gen = [&] (int k) {
101	        const __nv_bfloat16* aTile = sA + (size_t)k * 64 * 16;
102	        const __nv_bfloat16* bTile = sB + (size_t)k * N * 16;
103	        wgs::SmemDesc dA = wgs::make_desc_A_kmajor</*M=*/64, wgs::kSwizzleNone>(aTile);
104	        wgs::SmemDesc dB = wgs::make_desc_B_kmajor</*N=*/N,  wgs::kSwizzleNone>(bTile);
105	        return cuda::std::pair<wgs::SmemDesc, wgs::SmemDesc>(dA, dB);
106	    };
107	
108	    // The full choreography: fence → (k=0 overwrite, k>0 accumulate) →
109	    // commit → wait_group<0>. Both operands Major-K ⇒ TransA=0, TransB=0
110	    // (cute Major::K == 0); the wgmma reads D[m,n] = Σ_k A[m,k]·B[n,k].
111	    wgs::wgmma_mainloop_kchain<N, /*TransA=*/0, /*TransB=*/0>(acc, k_steps, gen);
112	
113	    // Epilogue: store each thread's N/2 fragment regs to the right (row,col)
114	    // of the M×N output using the authoritative fragment decode.
115	    #pragma unroll
116	    for (int i = 0; i < wgs::WgmmaAccum<N>::kRegs; ++i) {
117	        int row, col;
118	        wgs::wgmma_frag_decode(tid, i, N, row, col);
119	        gD[row * N + col] = acc.c[i];
120	    }
121	#else
122	    (void)gA; (void)gB; (void)gD; (void)k_steps;
123	#endif
124	}
125	
126	// Pipelined variant: producer/consumer warpgroup split staging K-tiles through
127	// an mbarrier ring (tile_pipeline.cuh), proving the choreography. Same numerics
128	// as the unpipelined kernel above (gate c). Uses blockDim.x = 256 (WG0
129	// producer + WG1 consumer).
130	template <int N, int PipeDepth>
131	__global__ void __launch_bounds__(256)
132	gemm_pipelined_kernel(
133	    const __nv_bfloat16* __restrict__ gA,
134	    const __nv_bfloat16* __restrict__ gB,
135	    float* __restrict__ gD,
136	    int k_steps
137	) {
138	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
139	    wgs::tc_pipelined_gemm_m64nNk16<N, PipeDepth>(gA, gB, gD, k_steps);
140	#else
141	    (void)gA; (void)gB; (void)gD; (void)k_steps;
142	#endif
143	}
144	
145	// =========================================================================
146	//  Host launchers (torch-callable).
147	// =========================================================================
148	
149	static size_t single_tile_smem_bytes(int N, int k_steps) {
150	    return (size_t)k_steps * (64 * 16 + N * 16) * sizeof(__nv_bfloat16);
151	}
152	
153	// Launch the unpipelined single-tile / K-loop GEMM for a compile-time N.
154	template <int N>
155	static torch::Tensor run_single_tile(torch::Tensor A, torch::Tensor B, int k_steps) {
156	    TORCH_CHECK(A.scalar_type() == torch::kBFloat16, "A must be bf16");
157	    TORCH_CHECK(B.scalar_type() == torch::kBFloat16, "B must be bf16");
158	    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA");
159	    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "inputs must be contiguous");
160	    TORCH_CHECK(A.numel() == (int64_t)k_steps * 64 * 16, "A numel mismatch");
161	    TORCH_CHECK(B.numel() == (int64_t)k_steps * N * 16,  "B numel mismatch");
162	
163	    auto D = torch::empty({64, N},
164	                          torch::dtype(torch::kFloat32).device(A.device()));
165	    size_t smem = single_tile_smem_bytes(N, k_steps);
166	    auto stream = at::cuda::getCurrentCUDAStream();
167	
168	    // Allow > 48 KB dynamic smem (opt-in attribute) for larger k_steps.
169	    cudaFuncSetAttribute(gemm_single_tile_kernel<N>,
170	                         cudaFuncAttributeMaxDynamicSharedMemorySize,
171	                         (int)smem);
172	    gemm_single_tile_kernel<N><<<1, 128, smem, stream>>>(
173	        reinterpret_cast<const __nv_bfloat16*>(A.data_ptr()),
174	        reinterpret_cast<const __nv_bfloat16*>(B.data_ptr()),
175	        D.data_ptr<float>(), k_steps);
176	    C10_CUDA_CHECK(cudaGetLastError());
177	    return D;
178	}
179	
180	// Pipelined launcher (compile-time N + depth).
181	template <int N, int PipeDepth>
182	static torch::Tensor run_pipelined(torch::Tensor A, torch::Tensor B, int k_steps) {
183	    TORCH_CHECK(A.scalar_type() == torch::kBFloat16 && B.scalar_type() == torch::kBFloat16);
184	    TORCH_CHECK(A.is_cuda() && B.is_cuda() && A.is_contiguous() && B.is_contiguous());
185	    auto D = torch::empty({64, N},
186	                          torch::dtype(torch::kFloat32).device(A.device()));
187	    // Ring of PipeDepth stages, each one A(64×16)+B(N×16) bf16 tile + the
188	    // mbarrier words.
189	    size_t ring = (size_t)PipeDepth * (64 * 16 + N * 16) * sizeof(__nv_bfloat16);
190	    size_t bars = (size_t)PipeDepth * 2 * sizeof(unsigned long long); // full+empty
191	    size_t smem = ring + bars + 256;  // slack for alignment
192	    auto stream = at::cuda::getCurrentCUDAStream();
193	    cudaFuncSetAttribute(gemm_pipelined_kernel<N, PipeDepth>,
194	                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
195	    gemm_pipelined_kernel<N, PipeDepth><<<1, 256, smem, stream>>>(
196	        reinterpret_cast<const __nv_bfloat16*>(A.data_ptr()),
197	        reinterpret_cast<const __nv_bfloat16*>(B.data_ptr()),
198	        D.data_ptr<float>(), k_steps);
199	    C10_CUDA_CHECK(cudaGetLastError());
200	    return D;
201	}
202	
203	// Dispatch over the runtime N to the compile-time template (the design's set).
204	static torch::Tensor gemm_tile(torch::Tensor A, torch::Tensor B, int N, int k_steps) {
205	    switch (N) {
206	        case 8:   return run_single_tile<8>(A, B, k_steps);
207	        case 16:  return run_single_tile<16>(A, B, k_steps);
208	        case 32:  return run_single_tile<32>(A, B, k_steps);
209	        case 64:  return run_single_tile<64>(A, B, k_steps);
210	        case 96:  return run_single_tile<96>(A, B, k_steps);
211	        case 128: return run_single_tile<128>(A, B, k_steps);
212	        default: TORCH_CHECK(false, "unsupported N ", N);
213	    }
214	}
215	
216	static torch::Tensor gemm_tile_pipelined(torch::Tensor A, torch::Tensor B,
217	                                         int N, int k_steps, int depth) {
218	    if (depth == 2) {
219	        switch (N) {
220	            case 64:  return run_pipelined<64, 2>(A, B, k_steps);
221	            case 128: return run_pipelined<128, 2>(A, B, k_steps);
222	            default: TORCH_CHECK(false, "pipelined: unsupported N ", N);
223	        }
224	    } else if (depth == 3) {
225	        switch (N) {
226	            case 64:  return run_pipelined<64, 3>(A, B, k_steps);
227	            case 128: return run_pipelined<128, 3>(A, B, k_steps);
228	            default: TORCH_CHECK(false, "pipelined: unsupported N ", N);
229	        }
230	    }
231	    TORCH_CHECK(false, "pipelined: unsupported depth ", depth);
232	}
233	
234	// =========================================================================
235	//  Occupancy / refuse probe (gate e). The faithful "occupancy >= 1 or refuse"
236	//  contract: query cudaOccupancyMaxActiveBlocksPerMultiprocessor for a given
237	//  dynamic-smem request; if it is 0 the launch would not be resident → REFUSE
238	//  (return 0) WITHOUT launching (no hang). Also exercises the hard failure
239	//  path: a smem request beyond the device max returns
240	//  cudaErrorLaunchOutOfResources promptly (asserted in python).
241	// =========================================================================
242	static int64_t occupancy_for_smem(int64_t requested_smem_bytes) {
243	    int numBlocks = 0;
244	    cudaError_t e = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
245	        &numBlocks, gemm_single_tile_kernel<128>, 128,
246	        (size_t)requested_smem_bytes);
247	    if (e != cudaSuccess) {
248	        // The query itself rejected the config (e.g. > device max): clear the
249	        // sticky error and report 0 occupancy (refuse). No kernel was launched.
250	        cudaGetLastError();
251	        return 0;
252	    }
253	    return (int64_t)numBlocks;
254	}
255	
256	// Actually attempt an oversized launch and return the cuda error code (the
257	// test asserts it is cudaErrorLaunchOutOfResources, i.e. it fails fast, no
258	// hang). We deliberately request more dynamic smem than any H100 SM has.
259	static int64_t probe_oversized_launch(int64_t requested_smem_bytes) {
260	    auto stream = at::cuda::getCurrentCUDAStream();
261	    // Do NOT set the attribute high enough (the request exceeds the cap); the
262	    // launch must be rejected at launch time.
263	    gemm_single_tile_kernel<128><<<1, 128, (size_t)requested_smem_bytes, stream>>>(
264	        nullptr, nullptr, nullptr, 0);
265	    cudaError_t e = cudaGetLastError();
266	    return (int64_t)e;  // python compares against cudaErrorLaunchOutOfResources (7? -> see test)
267	}
268	
269	// Report the H100 SM dynamic-smem cap so the test can size the oversized probe.
270	static int64_t device_max_dynamic_smem() {
271	    int v = 0;
272	    int dev = 0; cudaGetDevice(&dev);
273	    cudaDeviceGetAttribute(&v, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
274	    return (int64_t)v;
275	}
